<?php require dirname(__DIR__).'/includes/app.php';require_admin();$notice='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';if($a==='home'){write_json('home.json',['hero_eyebrow'=>trim((string)$_POST['hero_eyebrow']),'hero_title'=>trim((string)$_POST['hero_title']),'hero_text'=>trim((string)$_POST['hero_text']),'about_title'=>trim((string)$_POST['about_title']),'about_text'=>trim((string)$_POST['about_text']),'contact_title'=>trim((string)$_POST['contact_title']),'contact_text'=>trim((string)$_POST['contact_text'])]);$notice='Homepage saved.';}if($a==='seo'){$x=read_json('seo.json',[]);$x['home']=['title'=>trim((string)$_POST['title']),'description'=>trim((string)$_POST['description']),'keywords'=>trim((string)$_POST['keywords'])];write_json('seo.json',$x);$notice='SEO saved.';}if($a==='service_add'){$x=services();$x[]=['id'=>bin2hex(random_bytes(6)),'name'=>trim((string)$_POST['name']),'description'=>trim((string)$_POST['description'])];write_json('services.json',$x);$notice='Service added.';}if($a==='service_delete'){$x=array_values(array_filter(services(),fn($s)=>($s['id']??'')!==($_POST['id']??'')));write_json('services.json',$x);$notice='Service removed.';}if($a==='quote_status'){$x=read_json('quotes.json',[]);foreach($x as &$q)if(($q['id']??'')===($_POST['id']??''))$q['status']=(string)$_POST['status'];unset($q);write_json('quotes.json',$x);$notice='Quote updated.';}}
$h=home_content();$s=services();$m=seo('home');$quotes=array_reverse(read_json('quotes.json',[]));?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Content Manager</title><link rel="stylesheet" href="<?=e(asset_url('/admin/admin.css'))?>"></head><body><aside><div class="admin-logo">GB</div><h2>Galindos Builders</h2><a href="<?=e(site_url('/admin/'))?>">Projects & Tabs</a><a href="#home">Homepage</a><a href="#services">Services</a><a href="#seo">SEO</a><a href="#quotes">Quote Requests</a><a href="<?=e(site_url('/'))?>" target="_blank">View Website ↗</a></aside><main class="admin-main"><header><div><small>WEBSITE ADMIN</small><h1>Content Manager</h1></div></header><?php if($notice):?><div class="success"><?=e($notice)?></div><?php endif;?><section class="panel" id="home"><h2>Homepage Content</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="home"><?php foreach(['hero_eyebrow'=>'Hero Eyebrow','hero_title'=>'Hero Title','hero_text'=>'Hero Text','about_title'=>'About Title','about_text'=>'About Text','contact_title'=>'Contact Title','contact_text'=>'Contact Text'] as $k=>$label):?><label class="<?=str_contains($k,'text')?'full':''?>"><?=$label?><?php if(str_contains($k,'text')):?><textarea name="<?=$k?>" rows="4"><?=e($h[$k])?></textarea><?php else:?><input name="<?=$k?>" value="<?=e($h[$k])?>"><?php endif;?></label><?php endforeach;?><button>Save Homepage</button></form></section><section class="panel" id="services"><h2>Services</h2><?php foreach($s as $x):?><div class="admin-row"><div><b><?=e($x['name'])?></b><p><?=e($x['description'])?></p></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="service_delete"><input type="hidden" name="id" value="<?=e($x['id'])?>"><button class="danger">Delete</button></form></div><?php endforeach;?><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="service_add"><label>Service Name<input name="name" required></label><label class="full">Description<textarea name="description" required></textarea></label><button>Add Service</button></form></section><section class="panel" id="seo"><h2>SEO Controls</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="seo"><label class="full">Page Title<input name="title" value="<?=e($m['title'])?>"></label><label class="full">Meta Description<textarea name="description"><?=e($m['description'])?></textarea></label><label class="full">Keywords<input name="keywords" value="<?=e($m['keywords'])?>"></label><button>Save SEO</button></form></section><section class="panel" id="quotes"><h2>Contact / Quote Submissions</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Customer</th><th>Project</th><th>Message</th><th>Status</th></tr></thead><tbody><?php foreach($quotes as $q):?><tr><td><?=e(substr($q['created_at']??'',0,10))?></td><td><b><?=e($q['name'])?></b><br><?=e($q['email'])?><br><?=e($q['phone'])?></td><td><?=e($q['project'])?><br><?=e($q['location'])?></td><td><?=e($q['message'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="quote_status"><input type="hidden" name="id" value="<?=e($q['id'])?>"><select name="status" onchange="this.form.submit()"><?php foreach(['New','Contacted','Quoted','Won','Closed'] as $st):?><option <?=$st===($q['status']??'New')?'selected':''?>><?=$st?></option><?php endforeach;?></select></form></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>